// Belt-and-suspenders check for the one 409 shape this workflow accepts as
// benign: the case must actually already be in human_review. Any other
// state here means post-for-review 409'd for a real reason (e.g. the case
// is still 'verifying' or already terminal) and this workflow should not
// paper over that by proceeding to request an approval that cannot be
// recorded -- desk/api.py's POST /cases/{id}/decision itself would 409
// again downstream, but failing loudly here is cheaper to debug.
const state = $input.item.json.state;
if (state !== 'human_review') {
  throw new Error(`post-for-review 409'd and case ${$input.item.json.id} is in state '${state}', not human_review -- refusing to request approval`);
}
return [$input.item];
